    private static LessonSeed LongLesson(
        int order,
        string title,
        string summary,
        string coreIdea,
        string formula,
        string workedExample,
        string visualExplanation,
        string commonMistake,
        (string Prompt, string Correct, string WrongOne, string WrongTwo, string Explanation)[] checks)
    {
        var content = $"""
            {summary}

            Основная идея. {coreIdea}

            Формула. {formula}

            План решения. 1. Определи, что известно и что нужно найти. 2. Выбери правило и проверь, что его условия подходят. 3. Подставь данные и объясни, что означает результат.

            Разобранный пример. {workedExample}

            Наглядное объяснение. {visualExplanation}

            Типичная ошибка. {commonMistake}

            Итог урока. Проверь себя: объясни главную идею своими словами и реши пример, не подглядывая в формулу.
            """;

        var tasks = checks.Select((check, index) => Choice(
            index + 1,
            check.Prompt,
            "Проверь понимание",
            check.Explanation,
            (check.Correct, true),
            (check.WrongOne, false),
            (check.WrongTwo, false))).ToArray();

        return new LessonSeed(order, title, summary, content, tasks);
    }

    private static (string Prompt, string Correct, string WrongOne, string WrongTwo, string Explanation) Check(
        string prompt,
        string correct,
        string wrongOne,
        string wrongTwo,
        string explanation) => (prompt, correct, wrongOne, wrongTwo, explanation);
}
